   * A factory function to create the reference object from within an injection context.
   * @default () => inject(ElementRef).nativeElement
   *
   * @remarks
   * The reference object is used to store the instance of the class in a map so the
   * returned value must identifiable unique spanning the dependency tree
   * Typically, you would use a DOM element or Directive instance.
   */
  resolveIn?: Type<object> | (() => object);
};

/**
 * Decorator that marks a class as dynamically resolvable via DI or in the DOM tree.
 *
 * @usageNotes
 * Marking a class with @Resolvable provides enhanced functionality
 * to automatically resolve a class instance at the current level of
 * the dependency tree when resolvable criteria are not met.
 */
export function Resolvable(options?: ResolvableOptions): TypeDecorator {
  const resolveIn = options?.resolveIn;
  const getResolveIn: () => object | null = () => {
    const fn = isConstructor(resolveIn)
      ? () => inject(resolveIn)
      : isFunction(resolveIn)
        ? () => resolveIn()
        : () => injectElement();
    try {
      return fn();
    } catch {
      return null;
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return function (base: any) {
    class R extends base {
      static __NG_ELEMENT_ID__ = (flags: number): R | null => {
        const { host, self, skipSelf } = {
          host: !!(flags & 1),
          self: !!(flags & 2),
          skipSelf: !!(flags & 4),
        };

        let inj = inject(Injector, { optional: true, self, host, skipSelf });
        while (inj) {
          const ref = runInInjectionContext(inj, getResolveIn);
          if (ref) {
            const map = getInstanceMap(ref);
            if (map.has(R)) {
              return map.get(R) as R;
            }
          }
          if (self || host) {
            break;
          }
          inj = inj.get(Injector, null, { optional: true, skipSelf: true });
        }

        if (skipSelf) {
          return null; // We shouldn't resolve instances in places we don't own
        }

        const ref = getResolveIn();
        if (!ref) {
          return null; // If we can't resolve the reference, we can't create an instance
        }

        // Try to resolve the instance in the injector of the reference,
        // This way, it would be as if R was provided in the reference providers.
        return runInInjectionContext(
          instanceInjector(ref, { optional: true }) ?? inject(Injector),
          () => {
            const instance = new R();
            getInstanceMap(ref).set(R, instance);
            return instance;
          },
        );
      };
    }

    Object.defineProperty(R, 'name', { value: base.name });
    return R;
  };
}

function getInstanceMap(ref: object): Map<Type<object>, object> {
  if (!(ref as Record<symbol, unknown>)[RESOLVABLE]) {
    Object.defineProperty(ref, RESOLVABLE, { value: new Map() });
  }
  return (ref as Record<symbol, unknown>)[RESOLVABLE] as Map<Type<object>, object>;
}

