import type { Type, TypeDecorator } from '@angular/core';
import { inject, Injector, runInInjectionContext } from '@angular/core';
import { injectElement, instanceInjector, isConstructor, isFunction } from '@terseware/utils';

const RESOLVABLE: unique symbol = Symbol('RESOLVABLE');

export type ResolvableOptions = {
  /**
   * Whether to inherit the resolvable instance from the parent injector.
   * - `true`: Resolve the instance from the host or any parent.
   * - `false`: Resolve the instance from the host only.
   * @default false
   */
  inherit?: boolean;

  /**
   * A factory function to create the reference object from within an injection context.
   * @defaultValue `() => inject(ElementRef).nativeElement`
   *
   * @remarks
   * Must return a stable, unique object spanning the dependency tree (e.g. a DOM element
   * or directive instance). Used as the WeakMap-style key for per-element instance caching.
   */
  resolveIn?: Type<object> | (() => object);
};

/**
 * Decorator that marks a class as dynamically resolvable via DI or in the DOM tree.
 *
 * @remarks
 * Hooks into Angular's `__NG_ELEMENT_ID__` protocol so that `inject(MyResolvable)`
 * participates in normal element-injector resolution. Instances are cached per reference
 * object (default: host element), so multiple directives on the same element share one
 * instance.
 */
export function Resolvable(options?: ResolvableOptions): TypeDecorator {
  const { resolveIn, inherit = false } = options ?? {};

  const getResolveIn: () => object | null = () => {
    const fn = isConstructor(resolveIn)
      ? () => inject(resolveIn)
      : isFunction(resolveIn)
        ? () => resolveIn()
        : () => injectElement();
    try {
      return fn();
    } catch {
      return null;
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return function (base: any) {
    class R extends base {
      static __NG_ELEMENT_ID__ = (flags: number): R | null => {
        // InjectFlags bits (stable since Angular 9):
        //   Host     = 1
        //   Self     = 2
        //   SkipSelf = 4
        //   Optional = 8
        const isHost = !!(flags & 1);
        const isSelf = !!(flags & 2);
        const isSkipSelf = !!(flags & 4);

        // Walk the injector tree looking for an existing cached instance.
        // __NG_ELEMENT_ID__ is called inside Angular's DI machinery — inject() is valid here.
        const seen = new Set<Injector>();
        let inj: Injector | null = inject(Injector, {
          optional: true,
          self: isSelf,
          host: isHost,
          skipSelf: isSkipSelf,
        });

        while (inj && !seen.has(inj)) {
          seen.add(inj);

          const ref = runInInjectionContext(inj, getResolveIn);
          if (ref) {
            const map = getInstanceMap(ref);
            if (map.has(R)) return map.get(R) as R;
          }

          // Non-inherited resolution stops after the first injector.
          if (!inherit || isSelf || isHost) break;

          // Walk up. EnvironmentInjector.get(Injector, null, { skipSelf }) returns itself —
          // detect that to avoid an infinite loop.
          const parent = inj.get(Injector, null, { optional: true, skipSelf: true });
          inj = parent === inj ? null : parent;
        }

        // SkipSelf-only injection: never create, only look up.
        if (isSkipSelf) return null;

        // No cached instance found — create one in ref's node injector so that
        // inject() calls inside the constructor resolve from the correct element context.
        const ref = getResolveIn();
        if (!ref) return null;

        // instanceInjector is safe here: we're inside __NG_ELEMENT_ID__ (injection context).
        // Prefer ref's node injector so node-scoped tokens (ElementRef, CDRef, etc.) resolve
        // correctly. Fall back to the current injector if ref has no lView (e.g. plain object).
        const targetInjector =
          instanceInjector(ref, { optional: true }) ?? inject(Injector);

        return runInInjectionContext(targetInjector, () => {
          const instance = new R();
          getInstanceMap(ref).set(R, instance);
          return instance;
        });
      };
    }

    Object.defineProperty(R, 'name', { value: base.name });
    return R;
  };
}

function getInstanceMap(ref: object): Map<Type<object>, object> {
  if (!(ref as Record<symbol, unknown>)[RESOLVABLE]) {
    Object.defineProperty(ref, RESOLVABLE, { value: new Map(), configurable: false });
  }
  return (ref as Record<symbol, unknown>)[RESOLVABLE] as Map<Type<object>, object>;
}
```

The meaningful changes:

- **`inherit` is actually used** — the walk-up loop was unconditional before; now it only continues when `inherit: true`. Without it, `@Resolvable()` (default) would always walk up to the root, defeating the purpose of scoping.
- **`isSkipSelf` stops creation** — previously `skipSelf` only affected the initial `inject(Injector)` call, but the creation path at the bottom ran regardless. Now it returns `null` early.
- **`instanceInjector` called without `options.injector`** — since `__NG_ELEMENT_ID__` is an injection context, `inject()` works fine. Passing `inj` (the walker injector) was wrong — you want `ref`'s node injector, not whatever injector you happened to be walking through.
- **`configurable: false` on the map property** — minor hardening so nothing accidentally redefines `RESOLVABLE` on the ref object.

